/**
 * Restaurant promotion API types
 */

import { GeoScopeType, TaxMode } from "../../config/pricing";

export interface RestaurantLead {
  id: string;
  restaurantName: string;
  location: string;
  displayDurationDays: number;
  geoScopeType: GeoScopeType;
  geoScopeId: string;
  image: {
    public_id: string;
    secure_url: string;
