40	export async function createEventAction(
41	  data: EventCreateRequestDTO,
42	  e2eExtras?: E2EEventExtras
43	): Promise<CreateEventActionResult> {
44	  // 2026-07-26 round-5: catch the mutation error path so we can distinguish
45	  // 401 (likely stale Bearer — user should log out and back in) from 403
46	  // (profileCompleted: false per backend spec — user should complete
47	  // onboarding). Anything else is a real 5xx and rethrows. We log + tag
48	  // Sentry with the next action so the form can render the right message.
49	  //
50	  // 401/403 are *returned* as a CreateEventActionResult, not re-thrown:
51	  // Next.js redacts thrown Server Action error messages/properties in
52	  // production (only a generic message + digest reach the client), so
53	  // PublishForm would have no reliable way to tell these apart from a
54	  // plain 5xx if we threw here. editEvent
55	  // (app/[locale]/e/[eventId]/edita/actions.ts) already returns rather
56	  // than throws for its own actionable failures — same convention.
57	  // Anything else stays a throw: there's no more specific client action
58	  // to take for a real 5xx anyway.
59	  let created;
60	  try {
61	    // 1. Create the event in your backend
62	    created = await createEvent(data, e2eExtras);
63	  } catch (err) {
64	    const status = (err as { status?: number })?.status;
65	    if (status === 401 || status === 403) {
66	      const nextAction =
67	        status === 401 ? "logout-and-relogin" : "complete-profile";
68	      console.error(
69	        `createEventAction: backend rejected with ${status} \u2014 ${status === 401 ? "Likely stale Bearer \u2014 user should log out and back in." : "Likely profileCompleted: false \u2014 user should complete profile onboarding."}`,
70	      );
71	      // Don't forward the caught `err` as-is: createEvent() embeds the raw
72	      // backend response body in its .message, which would otherwise reach
73	      // Sentry unredacted despite the extra.* fields below being carefully
74	      // scrubbed. A short, fixed-shape message keeps the actual diagnosis
75	      // (status/nextAction/field names) without the body's content. titleHint
76	      // is dropped too \u2014 an event title has no diagnostic value for an
77	      // auth/profile-completion failure, so there's no reason to send
78	      // user-controlled content to a third-party service for it.
79	      captureException(new Error(`createEvent rejected: ${status}`), {
80	        tags: {
81	          section: "publica-create",
82	          authStatus: String(status),
83	          nextAction,
84	        },
85	        extra: {
86	          dataFields: Object.keys(data ?? {}),
87	        },
88	      });
89	      return {
90	        success: false,
91	        reason: status === 401 ? "stale-session" : "profile-incomplete",
92	      };
93	    }
94	    throw err;
95	  }
96	
97	  // 2. Send email notification (fire-and-forget, non-blocking)
98	  // Uses `after` to ensure execution completes in serverless environments
99	  if (created?.slug && created?.title) {
100	    const { title, slug } = created;
101	    after(() => sendNewEventEmail(title, slug));
102	  }
103	
104	  // 3. Immediately expire cache tags for event lists and categorized collections
105	  // This ensures read-your-own-writes: the new event appears immediately
106	  updateTag(eventsTag);
107	  updateTag(eventsCategorizedTag);
108	  // Refresh the current request to reflect changes
109	  refresh();
110	
111	  // 4. Return the created event or result for your client
112	  return { success: true, event: created };
113	}
