360	export async function createPromotionCheckout(
361	  id: string,
362	  successUrl: string,
363	  cancelUrl: string,
364	): Promise<{ url: string }> {
365	  const { apiUrl, authToken } = await requireMutationAuth();
366	
367	  const response = await fetchWithHmac(
368	    `${apiUrl}/events/${id}/promotions/checkout`,
369	    {
370	      method: "POST",
371	      headers: {
372	        Accept: "application/json",
373	        "Content-Type": "application/json",
374	        Authorization: `Bearer ${authToken}`,
375	      },
376	      body: JSON.stringify({ successUrl, cancelUrl }),
377	      skipBodySigning: true,
378	    },
379	  );
380	
381	  if (!response.ok) {
382	    const errorText = await response.text();
383	    console.error("createPromotionCheckout: error response:", errorText);
384	    throw new Error(
385	      `HTTP error! status: ${response.status}, body: ${errorText}`,
386	    );
387	  }
388	
389	  const payload = await response.json();
390	  if (!payload || typeof payload.url !== "string") {
391	    throw new Error(
392	      "createPromotionCheckout: backend response missing url field",
393	    );
394	  }
395	
396	  return { url: payload.url };
397	}

